import os
import torch


class Config:
    """
    Configuration for the Relative-Velocity-Aligned Anchored-Mining Ensemble (RVA-AME) strategy.
    """

    # -------------------------------------------------------------------------
    # Directory and File Paths
    # -------------------------------------------------------------------------
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    WORKING_DIR = "./working/idea_40"

    # Metadata Paths (Generated by previous steps)
    TRAIN_METADATA_PATH = os.path.join(METADATA_DIR, "train_metadata.csv")
    VAL_METADATA_PATH = os.path.join(METADATA_DIR, "val_metadata.csv")
    TEST_METADATA_PATH = os.path.join(METADATA_DIR, "test_metadata.csv")

    # Tracking Data Paths
    TRAIN_TRACKING_PATH = os.path.join(INPUT_DIR, "train_player_tracking.csv")
    TEST_TRACKING_PATH = os.path.join(INPUT_DIR, "test_player_tracking.csv")

    # Submission Output
    SUBMISSION_DIR = "./submission"
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # Ensure necessary directories exist
    os.makedirs(WORKING_DIR, exist_ok=True)
    os.makedirs(SUBMISSION_DIR, exist_ok=True)

    # -------------------------------------------------------------------------
    # Global Constants
    # -------------------------------------------------------------------------
    SEED = 42
    N_JOBS = 12  # Number of vCPUs available
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

    # -------------------------------------------------------------------------
    # Data Processing & Gating Strategy
    # -------------------------------------------------------------------------
    # Relaxed Quadratic Gating: Keep pairs where min(dist) < 3.0 yards
    GATING_DISTANCE = 3.0

    # Sentinel Value for Ground Distance (non-physical value)
    SENTINEL_VALUE = -1.0

    # Feature Engineering Window (Timesteps at 10Hz)
    # Window [-10, +10] corresponds to +/- 1.0 second
    WINDOW_SIZE = 10

    # -------------------------------------------------------------------------
    # Feature Engineering Configuration
    # -------------------------------------------------------------------------
    # Use Relative Velocity as the coordinate basis
    USE_RELATIVE_VELOCITY_ALIGNMENT = True

    # Explicit Interaction Primitives
    USE_TTC = True  # Time-To-Collision
    USE_JERK = True  # Derivative of Acceleration
    USE_ANGULAR_JERK = True  # Rotational changes

    # -------------------------------------------------------------------------
    # Training Strategy: Anchored Mining
    # -------------------------------------------------------------------------
    # Ratio of Random Easy Negatives (Anchors) to Positives in Expert Set
    ANCHOR_RATIO = 1.0

    # Probability threshold for mining Hard Negatives from Scouts
    HARD_NEGATIVE_THRESHOLD = 0.05

    # -------------------------------------------------------------------------
    # Model Hyperparameters (Dual-Ensemble)
    # -------------------------------------------------------------------------
    # LightGBM: Leaf-wise growth, Deep Trees
    LGBM_PARAMS = {
        "objective": "binary",
        "metric": "binary_logloss",
        "boosting_type": "gbdt",
        "learning_rate": 0.05,
        "n_estimators": 2000,
        "num_leaves": 256,  # High capacity
        "max_depth": 10,  # Deep trees
        "min_child_samples": 20,
        "subsample": 0.8,
        "colsample_bytree": 0.8,
        "reg_alpha": 0.1,
        "reg_lambda": 0.1,
        "n_jobs": N_JOBS,
        "verbose": -1,
        "is_unbalance": True,  # Handle class imbalance internally
    }

    # XGBoost: Level-wise growth, Deep Trees
    XGB_PARAMS = {
        "objective": "binary:logistic",
        "eval_metric": "logloss",
        "learning_rate": 0.05,
        "n_estimators": 2000,
        "max_depth": 10,  # Deep trees
        "min_child_weight": 1,
        "subsample": 0.8,
        "colsample_bytree": 0.8,
        "reg_alpha": 0.1,
        "reg_lambda": 0.1,
        "n_jobs": N_JOBS,
        "tree_method": "hist",
        "device": "cuda" if torch.cuda.is_available() else "cpu",
        # scale_pos_weight is typically set dynamically based on batch/fold stats
    }

    # Training Control
    EARLY_STOPPING_ROUNDS = 50

    # -------------------------------------------------------------------------
    # Execution Flags
    # -------------------------------------------------------------------------
    # Toggle for debugging with smaller dataset
    DEBUG = False
    DEBUG_SAMPLE_SIZE = 5000

    # Toggle for using cached processed features
    USE_CACHE = True
